//! Reader for the baseline oracle `fixtures/text-glyph-source/oracle.txt`
//! (generated by running the REAL opentype.js and the verbatim
//! `buildVectorTextGroup` of fbe4b8a3 over the eight bundled TTFs; see
//! HANDOFF.md), the FNV-1a digests it pins, and the recorded face built from
//! its GLYPH rows (advance and design commands of opentype.js, per unit).
use crate::object_document::object_text_layout_kernels::object_text_layout_kernel::model::FontAdvancePort;
use crate::object_document::object_text_layout_kernels::text_glyph_contours::{
    GlyphSegment, OutlineCommand,
};
use crate::object_document::object_text_layout_kernels::text_glyph_source::{
    scale_commands, DesignCommand, DesignPoint, GlyphSourceError, GlyphSourcePort,
};
use serde_json::Value;
use std::collections::HashMap;

pub(crate) const ORACLE: &str = include_str!("fixtures/text-glyph-source/oracle.txt");

/// Every data row with this tag, as JSON.
pub(crate) fn rows(tag: &str) -> Vec<Value> {
    ORACLE
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter_map(|line| {
            let (found, rest) = line.split_once(' ').expect("oracle row has a tag");
            (found == tag).then(|| serde_json::from_str(rest).expect("oracle row is JSON"))
        })
        .collect()
}

pub(crate) fn num(value: &Value) -> f64 {
    value.as_f64().expect("oracle number")
}

pub(crate) fn text(value: &Value) -> &str {
    value.as_str().expect("oracle string")
}

pub(crate) fn items(value: &Value) -> &Vec<Value> {
    value.as_array().expect("oracle array")
}

/// `[[x, y, onCurve, lastPointOfContour], ...]`.
pub(crate) fn points(value: &Value) -> Vec<DesignPoint> {
    items(value)
        .iter()
        .map(|row| {
            let r = items(row);
            DesignPoint {
                x: num(&r[0]),
                y: num(&r[1]),
                on_curve: r[2].as_i64() == Some(1),
                last_of_contour: r[3].as_i64() == Some(1),
            }
        })
        .collect()
}

/// `[["M", x, y], ["Q", x1, y1, x, y], ["Z"], ...]` in font units.
pub(crate) fn design(value: &Value) -> Vec<DesignCommand> {
    items(value)
        .iter()
        .map(|row| {
            let r = items(row);
            match text(&r[0]) {
                "M" => DesignCommand::Move {
                    x: num(&r[1]),
                    y: num(&r[2]),
                },
                "L" => DesignCommand::Line {
                    x: num(&r[1]),
                    y: num(&r[2]),
                },
                "Q" => DesignCommand::Quad {
                    x1: num(&r[1]),
                    y1: num(&r[2]),
                    x: num(&r[3]),
                    y: num(&r[4]),
                },
                "Z" => DesignCommand::Close,
                other => panic!("unexpected design command {other}"),
            }
        })
        .collect()
}

/// The same rows as final pixel-space commands (`getPath` output).
pub(crate) fn outline(value: &Value) -> Vec<OutlineCommand> {
    items(value)
        .iter()
        .map(|row| {
            let r = items(row);
            match text(&r[0]) {
                "M" => OutlineCommand::Move {
                    x: num(&r[1]),
                    y: num(&r[2]),
                },
                "L" => OutlineCommand::Line {
                    x: num(&r[1]),
                    y: num(&r[2]),
                },
                "Q" => OutlineCommand::Quad {
                    x1: num(&r[1]),
                    y1: num(&r[2]),
                    x: num(&r[3]),
                    y: num(&r[4]),
                },
                "Z" => OutlineCommand::Close,
                other => panic!("unexpected outline command {other}"),
            }
        })
        .collect()
}

/// FNV-1a 64 exactly as the generator's `Fnv` (`-0` hashes as `+0`).
pub(crate) struct Fnv(u64);

impl Fnv {
    pub(crate) fn new() -> Self {
        Fnv(0xcbf2_9ce4_8422_2325)
    }
    pub(crate) fn byte(&mut self, value: u8) {
        self.0 = (self.0 ^ u64::from(value)).wrapping_mul(0x0100_0000_01b3);
    }
    pub(crate) fn u16(&mut self, value: u16) {
        for byte in value.to_le_bytes() {
            self.byte(byte);
        }
    }
    pub(crate) fn f64(&mut self, value: f64) {
        for byte in (value + 0.0).to_bits().to_le_bytes() {
            self.byte(byte);
        }
    }
    pub(crate) fn hex(&self) -> String {
        format!("{:016x}", self.0)
    }
    /// Tag byte (M1 L2 Q3 C4 Z5), then each coordinate.
    pub(crate) fn outline(&mut self, commands: &[OutlineCommand]) {
        for command in commands {
            match *command {
                OutlineCommand::Move { x, y } => {
                    self.byte(1);
                    self.f64(x);
                    self.f64(y);
                }
                OutlineCommand::Line { x, y } => {
                    self.byte(2);
                    self.f64(x);
                    self.f64(y);
                }
                OutlineCommand::Quad { x1, y1, x, y } => {
                    self.byte(3);
                    for v in [x1, y1, x, y] {
                        self.f64(v);
                    }
                }
                OutlineCommand::Cubic {
                    x1,
                    y1,
                    x2,
                    y2,
                    x,
                    y,
                } => {
                    self.byte(4);
                    for v in [x1, y1, x2, y2, x, y] {
                        self.f64(v);
                    }
                }
                OutlineCommand::Close => self.byte(5),
            }
        }
    }
    /// `u16` count, then point, handleIn, handleOut per segment.
    pub(crate) fn segments(&mut self, segments: &[GlyphSegment]) {
        self.u16(segments.len() as u16);
        for s in segments {
            for v in [
                s.point[0],
                s.point[1],
                s.handle_in[0],
                s.handle_in[1],
                s.handle_out[0],
                s.handle_out[1],
            ] {
                self.f64(v);
            }
        }
    }
}

/// A face rebuilt from GLYPH rows: opentype.js' own advance and design
/// commands per unit (not computed by the code under test). Asking for a unit
/// the generator did not record is a loud failure, never a default.
#[derive(Clone, Debug)]
pub(crate) struct RecordedFace {
    upm: f64,
    glyphs: HashMap<u16, (f64, Vec<DesignCommand>)>,
}

impl FontAdvancePort for RecordedFace {
    fn units_per_em(&self) -> f64 {
        self.upm
    }
    fn advance_units(&self, utf16_unit: u16) -> Option<f64> {
        self.glyphs.get(&utf16_unit).map(|glyph| glyph.0)
    }
}

impl GlyphSourcePort for RecordedFace {
    fn as_advance(&self) -> &dyn FontAdvancePort {
        self
    }
    fn outline(
        &self,
        utf16_unit: u16,
        x: f64,
        y: f64,
        size: f64,
    ) -> Result<Vec<OutlineCommand>, GlyphSourceError> {
        let glyph = self
            .glyphs
            .get(&utf16_unit)
            .unwrap_or_else(|| panic!("oracle has no glyph row for unit {utf16_unit}"));
        scale_commands(&glyph.1, self.upm, x, y, size)
    }
}

/// One recorded face per FONT row (all eight bundled keys); a face with no GLYPH
/// rows answers no unit, which is fine for a face the layout never selects.
pub(crate) fn recorded_faces() -> HashMap<String, RecordedFace> {
    let mut faces: HashMap<String, RecordedFace> = HashMap::new();
    for font in rows("FONT") {
        faces.insert(
            text(&font["font"]).to_string(),
            RecordedFace {
                upm: num(&font["upm"]),
                glyphs: HashMap::new(),
            },
        );
    }
    for glyph in rows("GLYPH") {
        let face = faces
            .get_mut(text(&glyph["font"]))
            .expect("GLYPH row names a FONT row");
        face.glyphs.insert(
            glyph["unit"].as_u64().expect("unit") as u16,
            (num(&glyph["adv"]), design(&glyph["cmds"])),
        );
    }
    faces
}
